import mongoose from 'mongoose';

// Audit trail for POS admin-PIN reset codes generated by support (routes/pinResetRoutes.js).
// Only the licence id and its last 5 characters are stored, never the full key.
const PinResetAuditSchema = new mongoose.Schema({
  adminId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', index: true },
  adminEmail: { type: String, default: '' },
  appId: { type: String, required: true },
  software: { type: mongoose.Schema.Types.ObjectId, ref: 'Software' },
  deviceId: { type: String, required: true, index: true },
  nonce: { type: String, required: true },
  requestedAt: { type: Date },            // "t" from the request code
  license: { type: mongoose.Schema.Types.ObjectId, ref: 'License', default: null },
  licenseKeyLast: { type: String, default: '' },
  activationFound: { type: Boolean, default: false },
  ip: { type: String, default: '' },
  userAgent: { type: String, default: '' },
  createdAt: { type: Date, default: Date.now, index: true },
}, { collection: 'pin_reset_audits' });

export default mongoose.model('PinResetAudit', PinResetAuditSchema);
